for crew, events in crew_events.items():
    events.sort()
    for i in range(1,len(events)):
        if events[i][0] < events[i-1][1]:
            print(f'OVERLAP: {crew} {events[i-1]} and {events[i]}')
            overlap += 1
print(f'Crew overlaps: {overlap}')
# Verify no skid overlap
skid_events = defaultdict(list)
for r in rows:
    if r['skid_id'] not in ('NONE',''):
